import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight } = ctx.THREE;

  const COLORS = {
    background: '#0b0b10',
    surface: '#101015',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    hairline: '#23232b',
    gradTop: '#121218',
    gradBot: '#0b0b10',
  };

  const root = new Group();
  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  // ------------------------------------------------------------------
  // Backdrop stage plane (7 x 6 at z = -2.5) carrying spec gradientStops
  // ------------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(COLORS.gradBot), color(COLORS.gradTop), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ------------------------------------------------------------------
  // Footer band group (animated as one set object)
  // ------------------------------------------------------------------
  const band = new Group();
  band.position.set(0, -1.4, 0); // sit low in the hub frame like a footer
  root.add(band);

  const BAND_W = 6.8;
  const BAND_H = 2.0;

  // Band body: thin machined slab so hairlines read etched, not drawn
  const bandGeo = new BoxGeometry(BAND_W, BAND_H, 0.06);
  const bandMat = new MeshStandardNodeMaterial({ roughness: 0.6, metalness: 0.2 });
  bandMat.colorNode = mix(color(COLORS.gradBot), color(COLORS.gradTop), uv().y);
  const bandMesh = new Mesh(bandGeo, bandMat);
  bandMesh.position.set(0, 0, -0.03);
  band.add(bandMesh);
  disposables.push(bandGeo, bandMat);

  // Hairline rules (specular-catching low roughness)
  const hairlineMat = new MeshStandardNodeMaterial({
    color: COLORS.hairline,
    roughness: 0.28,
    metalness: 0.5,
  });
  disposables.push(hairlineMat);

  const hairGeoTop = new BoxGeometry(BAND_W, 0.006, 0.012);
  const hairTop = new Mesh(hairGeoTop, hairlineMat);
  hairTop.position.set(0, BAND_H / 2 - 0.003, 0.008);
  band.add(hairTop);
  disposables.push(hairGeoTop);

  const hairGeoLegal = new BoxGeometry(BAND_W - 1.0, 0.006, 0.012);
  const hairLegal = new Mesh(hairGeoLegal, hairlineMat);
  hairLegal.position.set(0, -0.375, 0.008);
  band.add(hairLegal);
  disposables.push(hairGeoLegal);

  // Node-local grazing rim from upper left so hairlines pick a specular edge
  const rim = new DirectionalLight(0xe8ecf2, 0.8);
  rim.position.set(-4, 3, 1.5);
  rim.target = bandMesh;
  band.add(rim);

  // ------------------------------------------------------------------
  // Text content (verbatim from spec)
  // ------------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  let wordmarkItem = null;
  let legalItem = null;
  const columns = [];
  let currentCol = null;
  for (const item of items) {
    if (item.role === 'wordmark') wordmarkItem = item;
    else if (item.role === 'legal') legalItem = item;
    else if (item.role === 'column-header') {
      currentCol = { header: item, links: [] };
      columns.push(currentCol);
    } else if (item.role === 'link' && currentCol) {
      currentCol.links.push(item);
    }
  }

  const TEXT_Z = 0.04;

  // Wordmark block: left 2.0 units of the band, padding 0.5
  const leftPad = -BAND_W / 2 + 0.5; // -2.9
  if (wordmarkItem) {
    const wm = ctx.fontAtlas.createText(String(wordmarkItem.text), {
      fontSize: 34,
      color: COLORS.paper,
      align: 'left',
      letterSpacingPx: 0.7,
    });
    wm.position.set(leftPad, 0.5, TEXT_Z);
    band.add(wm);
  }

  // Accent bar beneath wordmark — the single brightest element
  const barGeo = new BoxGeometry(0.3, 0.02, 0.02);
  const barMat = new MeshStandardNodeMaterial({
    color: COLORS.accent,
    roughness: 0.5,
    metalness: 0.2,
  });
  barMat.emissiveNode = color(COLORS.accent).mul(1.4);
  const accentBar = new Mesh(barGeo, barMat);
  accentBar.position.set(leftPad + 0.15, 0.22, TEXT_Z);
  band.add(accentBar);
  disposables.push(barGeo, barMat);

  // Three link columns: 1.2w each, 0.375 gutters
  const COL_W = 1.2;
  const GUTTER = 0.375;
  const colsLeft = -BAND_W / 2 + 2.0 + 0.25; // right of the 2.0-unit wordmark block
  const hitboxes = [];
  const hoverStates = new Map();

  const navMap = {
    Features: 'hub-features',
    Collection: 'hub-collection',
    Pricing: 'hub-pricing',
    Journal: 'hub-journal',
  };

  const hitMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0,
    depthWrite: false,
  });
  disposables.push(hitMat);

  columns.forEach((col, ci) => {
    const colX = colsLeft + ci * (COL_W + GUTTER);

    const header = ctx.fontAtlas.createText(String(col.header.text), {
      fontSize: 9,
      color: '#8a8f99',
      align: 'left',
      letterSpacingPx: 1.1,
    });
    header.position.set(colX, 0.56, TEXT_Z);
    band.add(header);

    col.links.forEach((link, li) => {
      const y = 0.32 - li * 0.234; // 13px links, 1.8 line height
      const label = String(link.text);

      const linkGroup = new Group();
      linkGroup.position.set(colX, y, TEXT_Z);
      band.add(linkGroup);

      const paperText = ctx.fontAtlas.createText(label, {
        fontSize: 13,
        color: COLORS.paper,
        align: 'left',
      });
      const accentText = ctx.fontAtlas.createText(label, {
        fontSize: 13,
        color: COLORS.accent,
        align: 'left',
      });
      accentText.visible = false;
      linkGroup.add(paperText);
      linkGroup.add(accentText);

      const hitGeo = new PlaneGeometry(COL_W, 0.2);
      const hit = new Mesh(hitGeo, hitMat);
      hit.position.set(COL_W / 2 - 0.1, 0.02, 0.005);
      hit.userData.linkId = `link-${ci}-${li}`;
      hit.userData.label = label;
      linkGroup.add(hit);
      disposables.push(hitGeo);

      hitboxes.push(hit);
      hoverStates.set(hit.userData.linkId, {
        group: linkGroup,
        paperText,
        accentText,
        label,
      });
    });
  });

  // Legal line: full width, 0.375 above bottom edge, below second hairline
  if (legalItem) {
    const legal = ctx.fontAtlas.createText(String(legalItem.text), {
      fontSize: 9,
      color: '#a8adb6',
      align: 'left',
      letterSpacingPx: 0.4,
    });
    legal.position.set(leftPad, -0.66, TEXT_Z);
    band.add(legal);
  }

  // ------------------------------------------------------------------
  // Cinematic primitives from config (none shipped, but honor contract)
  // ------------------------------------------------------------------
  const prims = config.cinematicPrimitives ?? [];
  for (const primitive of prims) {
    const fn = ctx.primitives[primitive.name];
    if (fn) primitiveHandles.push(fn(band, primitive.params));
  }

  // ------------------------------------------------------------------
  // Mount: single fade-up of the whole band, no per-item stagger
  // ------------------------------------------------------------------
  const bandRestY = band.position.y;
  band.position.y = bandRestY - 0.2;
  const mountTl = gsap.timeline();
  mountTl.to(band.position, {
    y: bandRestY,
    duration: 0.5,
    ease: 'power2.out',
  });
  bandMat.transparent = true;
  bandMat.opacity = 0;
  mountTl.to(
    bandMat,
    {
      opacity: 1,
      duration: 0.5,
      ease: 'power2.out',
      onComplete: () => {
        bandMat.transparent = false;
        bandMat.opacity = 1;
      },
    },
    0
  );
  timelines.push(mountTl);

  // ------------------------------------------------------------------
  // Interaction handlers (bus-attached, no DOM)
  // ------------------------------------------------------------------
  function findState(obj) {
    let o = obj;
    while (o) {
      if (o.userData && o.userData.linkId) return hoverStates.get(o.userData.linkId);
      o = o.parent;
    }
    return null;
  }

  root.userData.interactive = hitboxes;
  root.userData.handlers = {
    pointerover: (obj) => {
      const st = findState(obj);
      if (!st) return;
      st.paperText.visible = false;
      st.accentText.visible = true;
      const tl = gsap.to(st.group.position, {
        z: TEXT_Z + 0.02,
        duration: 0.14,
        ease: 'power2.out',
      });
      timelines.push(tl);
    },
    pointerout: (obj) => {
      const st = findState(obj);
      if (!st) return;
      st.paperText.visible = true;
      st.accentText.visible = false;
      const tl = gsap.to(st.group.position, {
        z: TEXT_Z,
        duration: 0.14,
        ease: 'power2.out',
      });
      timelines.push(tl);
    },
    click: (obj) => {
      const st = findState(obj);
      if (!st) return;
      const tl = gsap.timeline();
      tl.to(st.group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.in' });
      tl.to(st.group.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'back.out(2)' });
      timelines.push(tl);
      const target = navMap[st.label];
      if (target) {
        ctx.emit('navigate', { to: target });
      } else {
        ctx.emit('footer-link', { label: st.label });
      }
    },
  };

  // ------------------------------------------------------------------
  // Cleanup
  // ------------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    root.traverse((o) => {
      if (o.geometry && typeof o.geometry.dispose === 'function') o.geometry.dispose();
    });
  };

  return root;
}
